 "path": "/home/USER/continual-arc-baselines/.workbench/stage1/HPL0-hermes-luna6-high-rnd0/frozen/seen/play/users/u034/system/state/workspace/programs/task-c1912175.py",
 "content": "from collections import deque, Counter

def components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 4 or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.pop()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx)); q.append((ny,nx))
            out.append((color, cells))
    return out

def is_three_cell_corner(cells):
    if len(cells) != 3:
        return False
    rs = [r for r,c in cells]; cs = [c for r,c in cells]
    if max(rs)-min(rs) != 1 or max(cs)-min(cs) != 1:
        return False
    return len(set(cells)) == 3

def transform(grid):
    out = [row[:] for row in grid]
    comps = components(grid)
    # The large bent marker is the long connected component with a clear L profile.
    candidates = []
    for color, cells in comps:
        if len(cells) < 7:
            continue
        rs = [r for r,c in cells]; cs = [c for r,c in cells]
        rh, cw = max(rs)-min(rs)+1, max(cs)-min(cs)+1
        # A long bent line has a substantially longer vertical and horizontal span.
        if rh >= 4 and cw >= 4 and (rh >= 2*cw or cw >= 2*rh or len(cells) >= rh+cw-1):
            candidates.append((len(cells), color))
    if not candidates:
        return out
    marker_color = max(candidates)[1]
    # Small three-cell right-angle objects are the designated shapes to paint.
    targets = [(color, cells) for color, cells in comps
               if color != marker_color and is_three_cell_corner(cells)]
    if targets:
        # Prefer the compact corner when only one is present; recolor it with marker color.
        _, cells = min(targets, key=lambda item: len(item[1]))
        for r, c in cells:
            out[r][c] = marker_color
    return out

if __name__ == '__main__':
    pass
