def components(grid):
    h, w = len(grid), len(grid[0])
    seen=set(); out=[]
    for r in range(h):
        for c in range(w):
            col=grid[r][c]
            if col in (4,) or (r,c) in seen: continue
            q=[(r,c)]; seen.add((r,c)); cells=[]
            while q:
                y,x=q.pop(); cells.append((y,x))
                for ny,nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=ny<h and 0<=nx<w and (ny,nx) not in seen and grid[ny][nx]==col:
                        seen.add((ny,nx)); q.append((ny,nx))
            out.append((col,cells))
    return out

