    out=[row[:] for row in grid]
    comps=components(grid)
    # The long L-shaped component marks the color to use.
    for col,cells in comps:
        rs=[r for r,c in cells]; cs=[c for r,c in cells]
        h=max(rs)-min(rs)+1; w=max(cs)-min(cs)+1
        if h>=4 and w>=4 and len(cells)>=h+w-2:
            marker=col
            # Replace the smallest compact L-shaped component (three cells).
            targets=[]
            for other,cc in comps:
                if other==marker or len(cc)!=3: continue
                rr=[r for r,c in cc]; xx=[c for r,c in cc]
                if max(rr)-min(rr)==1 and max(xx)-min(xx)==1:
                    targets.append(cc)
            if targets:
                for r,c in min(targets,key=len): out[r][c]=marker
            return out
    return out
