                    if 0<=ny<h and 0<=nx<w and (ny,nx) not in seen and grid[ny][nx]==col:
                        seen.add((ny,nx));q.append((ny,nx))
            out.append((col,cells))
    return out

def transform(grid):
    out=[row[:] for row in grid]
    comps=components(grid)
    # Find the unique 2x2 solid square. Its color is the paint color.
    squares=[]
    for col,cells in comps:
        s=set(cells)
        for r,c in cells:
            if {(r,c),(r+1,c),(r,c+1),(r+1,c+1)} <= s:
                squares.append((col, {(r,c),(r+1,c),(r,c+1),(r+1,c+1)}))
    # Select the largest square component, which serves as the source marker.
    if not squares: return out
    source_color=max(squares,key=lambda x:len(next(cs for co,cs in comps if co==x[0])))[0]
    # Recolor all separate L-triominoes to the source marker color.
    for col,cells in comps:
        if col==source_color or len(cells)!=3: continue
        rs=[r for r,c in cells]; cs=[c for r,c in cells]
        if max(rs)-min(rs)==1 and max(cs)-min(cs)==1:
            outcells=set(cells)
            # 3 cells inside a 2x2 bounding box forms an L.
            if len(outcells)==3:
                for r,c in cells: out[r][c]=source_color
    return out
