    h,w=len(grid),len(grid[0]); seen=set(); out=[]
    for r in range(h):
        for c in range(w):
            col=grid[r][c]
            if col==4 or (r,c) in seen: continue
            q=[(r,c)]; seen.add((r,c)); cells=[]
            while q:
                y,x=q.pop(); cells.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==col:
                        seen.add((yy,xx)); q.append((yy,xx))
            out.append((col,cells))
    return out

def transform(grid):
    out=[row[:] for row in grid]
    comps=components(grid)
    # Markers are the long continuous non-background lines; their color paints
    # the small 2x2 block objects of the same local motif.
    markers=[]
    for col,cells in comps:
        rs=[r for r,c in cells]; cs=[c for r,c in cells]
        rh=max(rs)-min(rs)+1; cw=max(cs)-min(cs)+1
        if len(cells)>=8 and max(rh,cw)>=6 and min(rh,cw)>=2:
            markers.append((len(cells),col))
    if not markers: return out
    marker=max(markers)[1]
    # The marked target is the isolated solid 2x2 square whose color is not
    # already the marker. In examples this is the square motif, not the lines.
    for col,cells in comps:
        if col==marker or len(cells)!=4: continue
        rs=[r for r,c in cells]; cs=[c for r,c in cells]
        if max(rs)-min(rs)==1 and max(cs)-min(cs)==1:
            s=set(cells)
            if all((r,c) in s for r in (min(rs),max(rs)) for c in (min(cs),max(cs))):
                for r,c in cells: out[r][c]=marker
    return out

