 "content": "def transform(grid):
    """Recolor the solid pattern matching the sparse line/angle marker.

    The marker is the component of a color with greatest bounding-box span;
    its color is transferred to the distinct component with identical shape
    (same normalized occupied coordinates).
    """
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if (r, c) in seen:
                continue
            seen.add((r, c))
            q = [(r, c)]
            cells = []
            while q:
                y, x = q.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx))
                        q.append((yy,xx))
            if color != grid[0][0]:
                minr=min(y for y,x in cells); maxr=max(y for y,x in cells)
                minc=min(x for y,x in cells); maxc=max(x for y,x in cells)
                shape=frozenset((y-minr,x-minc) for y,x in cells)
                comps.append((color,cells,(maxr-minr+1)*(maxc-minc+1),shape))
    # The pattern marker is spatially extensive but sparse. Compare bbox area
    # to occupied cells; solid matching instances have the same normalized shape.
    markers=[]
    for item in comps:
        color,cells,area,shape=item
        if len(cells) < area:
            markers.append(item)
    if not markers:
        return [row[:] for row in grid]
    marker=max(markers,key=lambda z:(z[2]-len(z[1]), z[2]))
    color,_,_,shape=marker
    out=[row[:] for row in grid]
    for other_color,cells,area,other_shape in comps:
        if other_color != color and other_shape == shape:
            for r,c in cells:
                out[r][c]=color
    return out
